"""Jev: Pick one node generated by aotn_node_helper."""

from typing import Any, ClassVar, Dict, List, Optional

from ...node_base import Node, NodeContext
from ...node_category import NodeCategory
from ...node_errors import NodeError
from ...field_types import object_list_problems, check_number
from ...integrations import jev
from ...system_access import finish


class PickOneNode(Node):
    """Ask Jev to pick one answer from your list; low confidence sends unsure."""

    node_type: ClassVar[str] = 'pick_one_node'
    display_name: ClassVar[str] = 'Jev: Pick one'
    default_alias: ClassVar[str] = 'Pick one'
    description: ClassVar[str] = 'Ask Jev to pick one answer from your list; low confidence sends unsure'
    category: ClassVar[str] = NodeCategory.AI
    primary_family: ClassVar[str] = 'Complex'
    tags: ClassVar[List[str]] = ['choose', 'classify', 'route', 'Jev']
    icon_name: ClassVar[str] = 'list-check'
    color_hint: ClassVar[str] = 'violet'
    group: ClassVar[Optional[str]] = 'AI Processing'
    selector_section: ClassVar[Optional[str]] = 'AI'
    input_ports: ClassVar[List[str]] = ['input']
    output_ports: ClassVar[List[str]] = ['default', 'details']
    input_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'input': {'name': 'Text to judge', 'description': 'The text Jev reads before picking an answer', 'data_type': 'string', 'required': True, 'sources': ['upstream', 'vault', 'configured']}}
    output_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'default': {'name': 'Answer', 'description': 'Exactly the picked answer, or unsure below the cutoff', 'data_type': 'string', 'required': True, 'to': ['downstream', 'vault']}, 'details': {'name': 'Pick details', 'description': "Every answer's score, confidence, model and token usage", 'data_type': 'var', 'required': False, 'to': ['vault']}}
    default_config: ClassVar[Dict[str, Any]] = {'input_source': 'Upstream payload', 'input_vault_key': '', 'input': '', 'question': 'Which team should handle this message?', 'choices': [{'id': 'answer_billing', 'answer': 'billing', 'description': 'Payments, refunds and invoices'}, {'id': 'answer_bug', 'answer': 'bug', 'description': 'Something in the app is broken'}, {'id': 'answer_other', 'answer': 'other', 'description': 'Anything else'}], 'api_key_secret': '', 'timeout': 20, 'unsure_below': 0.3, 'transient_output': True, 'dead_drop_passthrough': False, 'transient_outputs': [], 'vault_write': False, 'vault_write_key': '', 'vault_write_description': '', 'details_vault_write': False, 'details_vault_key': '', 'details_vault_description': ''}
    config_schema: ClassVar[Dict[str, Dict[str, Any]]] = {'input_source': {'type': 'select', 'label': 'Text source', 'options': ['Upstream payload', 'Vault', 'Configured'], 'tab': 'Source', 'section': 'Required Inputs', 'description': 'The text Jev reads before picking an answer'}, 'input_vault_key': {'type': 'string', 'label': 'Text Vault key', 'required': False, 'tab': 'Source', 'section': 'Required Inputs', 'vault_type': 'string', 'visible_when': {'input_source': 'Vault'}}, 'input': {'type': 'multiline', 'label': 'Text', 'height': 3, 'tab': 'Parameters', 'visible_when': {'input_source': 'Configured'}}, 'question': {'type': 'string', 'label': 'Question', 'required': True, 'placeholder': 'Which team should handle this message?', 'tab': 'Parameters'}, 'choices': {'type': 'object_list', 'label': 'Answers', 'add_label': 'Add answer', 'remove_label': 'Remove answer', 'id_prefix': 'answer_', 'min_items': 1, 'max_items': 255, 'unique_by': 'answer', 'item_schema': {'answer': {'type': 'string', 'label': 'Answer (sent on)', 'required': True}, 'description': {'type': 'string', 'label': 'What it means'}}, 'tab': 'Parameters'}, 'api_key_secret': {'type': 'string', 'label': 'API key (secrets store key)', 'secret': True, 'required': True, 'tab': 'Parameters'}, 'timeout': {'type': 'number', 'label': 'Give up after (seconds)', 'min': 1, 'max': 300, 'tab': 'Parameters'}, 'unsure_below': {'type': 'number', 'label': 'Unsure when sureness is under (0 to 1)', 'min': 0, 'max': 1, 'tab': 'Parameters'}}
    ui_hints: ClassVar[Dict[str, Any]] = {}
    error_definitions: ClassVar[List[Dict[str, Any]]] = [{'code': 'auth_failed', 'description': 'The API key is missing or was refused.', 'retryable': False}, {'code': 'timed_out', 'description': 'Jev did not answer before the deadline.', 'retryable': True}, {'code': 'provider_error', 'description': 'The AI service could not complete the request.', 'retryable': True}, {'code': 'undeclared_choice', 'description': 'The answer is not on your list (matching is exact).', 'retryable': False}]

    async def execute(self, context: NodeContext) -> None:
        # Check all routing keys before spending a request or writing anything.
        for enabled, key_field in (("vault_write", "vault_write_key"),
                                   ("details_vault_write", "details_vault_key")):
            if self.config.get(enabled) and not str(self.config.get(key_field) or "").strip():
                context.signal_error(NodeError("node_error", "Enter a Vault output key"))
                return
        if (self.config.get("vault_write") and self.config.get("details_vault_write")
                and self.config.get("vault_write_key", "").strip()
                == self.config.get("details_vault_key", "").strip()):
            context.signal_error(NodeError("node_error", "Answer and Pick details need different Vault keys"))
            return
        problems = object_list_problems(self.config_schema, self.config)
        question = self.config.get("question")
        if problems or not isinstance(question, str) or not question.strip():
            context.signal_error(NodeError("node_error", problems[0] if problems else "Enter a question"))
            return
        numbers = {}
        for field in ("timeout", "unsure_below"):
            value, problem = check_number(self.config_schema[field], self.config.get(field),
                                          self.default_config[field])
            if problem:
                context.signal_error(NodeError("node_error", f"Check {self.config_schema[field]['label']}"))
                return
            numbers[field] = value
        source = self.config.get("input_source")
        if source == "Upstream payload":
            text = context.inputs.get("input")
        elif source == "Vault":
            key = str(self.config.get("input_vault_key") or "").strip()
            text = context.memory_bank.read_persistent(key) if key else None
        elif source == "Configured":
            text = self.config.get("input")
        else:
            text = None
        if not isinstance(text, str) or not text.strip():
            context.signal_error(NodeError("node_error", "Choose non-empty text to judge"))
            return
        secret_ref = str(self.config.get("api_key_secret") or "").strip()
        try:
            api_key = context.get_secret(secret_ref) if secret_ref else None
        except Exception:
            api_key = None
        if not api_key:
            context.signal_error(NodeError("auth_failed", "The API key is missing or was refused"))
            return
        try:
            result = await jev.pick_one(text=text, question=question,
                                        criteria={row["answer"]: row.get("description", "")
                                                  for row in self.config["choices"]},
                                        api_key=api_key, timeout=numbers["timeout"])
        except jev.JevError as exc:
            messages = {"auth_failed": "The API key is missing or was refused",
                        "timed_out": "Jev did not answer before the deadline",
                        "provider_error": "The AI service could not complete the request",
                        "undeclared_choice": "The answer is not on your list (matching is exact)"}
            context.signal_error(NodeError(exc.code, messages[exc.code],
                                           retryable=exc.code in {"timed_out", "provider_error"}))
            return
        answer = "unsure" if result.confidence < numbers["unsure_below"] else result.answer
        if self.config.get("details_vault_write"):
            context.memory_bank.store_persistent(self.config["details_vault_key"].strip(),
                                                 result.details(), type_tag="var")
        finish(self, context, answer, "string")
